"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([["7381"],{11721(e,t,n){n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>r,default:()=>c,frontMatter:()=>s,metadata:()=>a,toc:()=>h});var a=n(20977),i=n(74848),o=n(28453);let s={slug:"the-week-we-stopped-failing-silently",title:"The week we stopped failing silently",authors:["olaf"],tags:["ai-coding","reliability","cost","benchmarks","multi-provider"],date:new Date("2026-07-13T00:00:00.000Z"),description:"A July 2026 cycle recap. An external SWE-bench baseline showed that almost half of AIFactory's failures were not wrong answers but empty patches \u2014 silent no-ops. We root-caused and fixed the dominant cause three ways, killed a second latent no-op, then shipped per-stage cost-aware model routing and measured a real 55 percent cost cut. This is the honest version, including a measurement that looked like a success and was actually a bug."},r,l={authorsImageUrls:[void 0]},h=[{value:"The number that started it",id:"the-number-that-started-it",level:2},{value:"Three defenses against the empty patch",id:"three-defenses-against-the-empty-patch",level:2},{value:"Then we made it cheaper, and caught ourselves doing it wrong",id:"then-we-made-it-cheaper-and-caught-ourselves-doing-it-wrong",level:2},{value:"What this proves",id:"what-this-proves",level:2},{value:"What is next",id:"what-is-next",level:2}];function d(e){let t={h2:"h2",li:"li",p:"p",ul:"ul",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.p,{children:"The most dangerous way for an autonomous coder to fail is quietly. A wrong patch\ngets caught by tests. A patch that never gets written looks, from a distance, a\nlot like a build that is still thinking. This cycle we put a number on that\ndistance and then closed it."}),"\n","\n",(0,i.jsx)(t.h2,{id:"the-number-that-started-it",children:"The number that started it"}),"\n",(0,i.jsx)(t.p,{children:"The Factory hub ran our first external benchmark: 50 real SWE-bench Verified\ntasks, driven through the live pipeline and scored by the official harness, not\nby us. AIFactory resolved 38 percent overall. But the informative slice was the\nfailure breakdown. When AIFactory produced a scorable patch, it was correct about\n79 percent of the time. The problem was that 22 of 50 runs produced no patch at\nall. Nearly half of our failures were empty. Silent."}),"\n",(0,i.jsx)(t.p,{children:"You cannot fix what you cannot see, so first we made it visible, and then we\nwent and found the cause."}),"\n",(0,i.jsx)(t.h2,{id:"three-defenses-against-the-empty-patch",children:"Three defenses against the empty patch"}),"\n",(0,i.jsx)(t.p,{children:"Two independent investigations converged on the same seam: the coding session\ncould stall on startup. Entering the agent client spawns the local CLI and its\nMCP tool servers, two of which are fetched over the network at connect time. On a\ncold or network-restricted runner that fetch could hang, no first model call ever\nhappened, and with no timeout anywhere on the path the session burned in silence\nstraight to the Kubernetes job deadline. Zero tokens, zero output, one empty\npatch."}),"\n",(0,i.jsx)(t.p,{children:"We fixed it in depth rather than in one place:"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsx)(t.li,{children:"A connect and first-token watchdog. If entering the session does not complete\nwithin a bounded window, it now fails fast into the existing retry path instead\nof hanging for an hour. A silent stall becomes a loud, recoverable error."}),"\n",(0,i.jsx)(t.li,{children:"Pre-baking the MCP tool servers into the runner image, so the network fetch\nthat caused the stall does not happen at run time at all."}),"\n",(0,i.jsx)(t.li,{children:"Bounding the rate-limit wait below the build deadline, so no single wait can\nconsume the whole build."}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:"While we were there we found a second, quieter no-op: a plan whose subtasks\nomitted a status field would select nothing, and the coder would exit reporting\nthat there was nothing to do. That was a one-line divergence between two loaders,\nand it was writing zero code on real plans. Fixed, with a regression test."}),"\n",(0,i.jsx)(t.h2,{id:"then-we-made-it-cheaper-and-caught-ourselves-doing-it-wrong",children:"Then we made it cheaper, and caught ourselves doing it wrong"}),"\n",(0,i.jsx)(t.p,{children:"The same benchmark gave our cost-aware routing work something to prove against.\nThe idea of RFC-0014 is simple: not every stage needs the most expensive model.\nPlanning benefits from a frontier model; bulk coding often does not. So we route\nper stage."}),"\n",(0,i.jsx)(t.p,{children:"The honest part is what happened when we first measured it. We ran the same tasks\nwith routing off and on, and got identical cost. That looked like the feature did\nnothing. It turned out routing genuinely did nothing, because the difficulty tier\nwas writing a fixed model into the task metadata that silently outranked the\nrouter. That is a real bug, and the measurement is what exposed it. We fixed the\nprecedence so routing is consulted before the static tier model, added a\ncapability floor so a hard task can never be routed below the model it needs, and\nre-measured."}),"\n",(0,i.jsx)(t.p,{children:"The second measurement was clean. On three identical tasks, routing on took\nplanning to a frontier model and coding to a cheap one, and cost dropped from\n6.48 to 2.91 US dollars, a 55 percent reduction, at essentially the same token\nvolume. The saving is the model mix, not less work, and every worker in the\ncompletion event is now stamped with the tier it ran at, so you can see it in the\ncockpit rather than take it on faith."}),"\n",(0,i.jsx)(t.h2,{id:"what-this-proves",children:"What this proves"}),"\n",(0,i.jsx)(t.p,{children:"That we treat reliability as a measurable property, not a vibe. The empty-patch\nrate was the dominant gap in a public benchmark, we found the mechanism, and we\ndefended against it in the image, in the session, and in the retry policy."}),"\n",(0,i.jsx)(t.p,{children:"That we would rather ship a fix we can defend than a number we cannot. The\nrouting story only counts because we were willing to notice that our first result\nwas wrong and say so."}),"\n",(0,i.jsx)(t.p,{children:"And that honesty scales: a benchmark that looked like a bad day was the best\nthing that happened to the coder all cycle."}),"\n",(0,i.jsx)(t.h2,{id:"what-is-next",children:"What is next"}),"\n",(0,i.jsx)(t.p,{children:"Turn the routing measurement into a standing matrix instead of a one-off, and get\nthe scored-resolve confirmation now that the benchmark patches are clean of\nscaffolding noise. Bring the second coder runtime, Codex, to the same bar as\nClaude; this cycle it learned to report its own failures out loud instead of\nexiting quietly, which is the prerequisite for trusting it at all. The gaps we\nhave not closed are written down in public issues, which is the only kind of\nroadmap worth having."})]})}function c(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},28453(e,t,n){n.d(t,{R:()=>s,x:()=>r});var a=n(96540);let i={},o=a.createContext(i);function s(e){let t=a.useContext(o);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),a.createElement(o.Provider,{value:t},e.children)}},20977(e){e.exports=JSON.parse('{"permalink":"/blog/the-week-we-stopped-failing-silently","source":"@site/blog/2026-07-13-the-week-we-stopped-failing-silently.md","title":"The week we stopped failing silently","description":"A July 2026 cycle recap. An external SWE-bench baseline showed that almost half of AIFactory\'s failures were not wrong answers but empty patches \u2014 silent no-ops. We root-caused and fixed the dominant cause three ways, killed a second latent no-op, then shipped per-stage cost-aware model routing and measured a real 55 percent cost cut. This is the honest version, including a measurement that looked like a success and was actually a bug.","date":"2026-07-13T00:00:00.000Z","tags":[{"inline":true,"label":"ai-coding","permalink":"/blog/tags/ai-coding"},{"inline":true,"label":"reliability","permalink":"/blog/tags/reliability"},{"inline":true,"label":"cost","permalink":"/blog/tags/cost"},{"inline":true,"label":"benchmarks","permalink":"/blog/tags/benchmarks"},{"inline":true,"label":"multi-provider","permalink":"/blog/tags/multi-provider"}],"readingTime":4.13,"hasTruncateMarker":true,"authors":[{"name":"Olaf Krasicki-Freund","title":"Creator of AIFactory","url":"https://github.com/olafkfreund","socials":{"github":"https://github.com/olafkfreund"},"imageURL":"https://github.com/olafkfreund.png","key":"olaf","page":null}],"frontMatter":{"slug":"the-week-we-stopped-failing-silently","title":"The week we stopped failing silently","authors":["olaf"],"tags":["ai-coding","reliability","cost","benchmarks","multi-provider"],"date":"2026-07-13T00:00:00.000Z","description":"A July 2026 cycle recap. An external SWE-bench baseline showed that almost half of AIFactory\'s failures were not wrong answers but empty patches \u2014 silent no-ops. We root-caused and fixed the dominant cause three ways, killed a second latent no-op, then shipped per-stage cost-aware model routing and measured a real 55 percent cost cut. This is the honest version, including a measurement that looked like a success and was actually a bug."},"unlisted":false,"prevItem":{"title":"A coder that cannot fake a green test","permalink":"/blog/a-coder-that-cannot-fake-a-green-test"},"nextItem":{"title":"Building on the latest models \u2014 with Copilot joining the coders","permalink":"/blog/build-on-the-latest-models"}}')}}]);